import{_ as e,o as a,c as t,ag as l}from"./chunks/framework.KxDd3USm.js";const m=JSON.parse('{"title":"09.4 磁盘容量与存取时间 ★★★","description":"","frontmatter":{},"headers":[],"relativePath":"09-计算机系统基础/04-磁盘.md","filePath":"09-计算机系统基础/04-磁盘.md"}'),r={name:"09-计算机系统基础/04-磁盘.md"};function s(i,o,p,n,d,c){return a(),t("div",null,[...o[0]||(o[0]=[l('<h1 id="_09-4-磁盘容量与存取时间-★★★" tabindex="-1">09.4 磁盘容量与存取时间 ★★★ <a class="header-anchor" href="#_09-4-磁盘容量与存取时间-★★★" aria-label="Permalink to &quot;09.4 磁盘容量与存取时间 ★★★&quot;">​</a></h1><h3 id="_6-1-容量计算" tabindex="-1">6.1 容量计算 <a class="header-anchor" href="#_6-1-容量计算" aria-label="Permalink to &quot;6.1 容量计算&quot;">​</a></h3><p>磁盘容量的通用形式：</p><p><strong>容量 = 记录面数 × 每面磁道数 × 每磁道扇区数 × 每扇区字节数</strong></p><p>注意“盘片数”不一定等于“记录面数”：一个盘片通常有两个面，但题目可能说明某些面不用。以题面为准。</p><p>例：磁盘有 4 个记录面，每面 2000 磁道，每磁道 100 扇区，每扇区 512 B：</p><p>容量 = 4×2000×100×512 = 409,600,000 B。</p><p>若按二进制 MiB 换算：409,600,000 / 2^20 = <strong>390.625 MiB</strong>。</p><p><strong>盘片数与记录面数算例</strong>：某磁盘有 3 张盘片，每张上下两面，但最上面和最下面两个外侧面不用来记录，因此记录面数不是 <code>3×2=6</code>，而是 <code>6−2=4</code>。若每面 1000 道、每道 50 扇区、每扇区 512 B，则容量：</p><p><code>4×1000×50×512 = 102,400,000 B</code>。</p><p>题目若直接给“磁头数”，传统磁盘中通常可把有效磁头数视为记录面数；若同时给盘片数和记录面数，以明确给出的记录面数为准。</p><h3 id="_6-2-平均存取时间" tabindex="-1">6.2 平均存取时间 <a class="header-anchor" href="#_6-2-平均存取时间" aria-label="Permalink to &quot;6.2 平均存取时间&quot;">​</a></h3><p><strong>磁盘存取时间 = 寻道时间 + 旋转等待时间 + 数据传输时间</strong></p><ul><li>寻道：磁头移动到目标磁道；</li><li>旋转等待：等目标扇区转到磁头下；</li><li>传输：真正读写数据。</li></ul><p>若转速为 RPM（转/分）：</p><ul><li>一圈时间 = 60 / RPM 秒 = 60,000 / RPM 毫秒；</li><li>平均旋转等待 = 半圈时间 = <strong>30,000 / RPM 毫秒</strong>；</li><li>读 x 个连续扇区（每道 S 个扇区）的传输时间 = 一圈时间 × x/S。</li></ul><p>例：7200 RPM，平均寻道 8 ms，每道 120 扇区，读取连续 3 扇区：</p><ol><li>一圈 = 60,000/7200 = 8.333 ms；</li><li>平均旋转等待 = 8.333/2 = 4.167 ms；</li><li>传输 = 8.333×3/120 = 0.208 ms；</li><li>平均存取 = 8+4.167+0.208 = <strong>12.375 ms</strong>。</li></ol><p>反向验算：3 个扇区是 1/40 圈，所以传输时间应是一圈 8.333 ms 的 1/40，即约 0.208 ms。</p><h4 id="连续与非连续存放-差别在于定位成本付几次" tabindex="-1">连续与非连续存放：差别在于定位成本付几次 <a class="header-anchor" href="#连续与非连续存放-差别在于定位成本付几次" aria-label="Permalink to &quot;连续与非连续存放：差别在于定位成本付几次&quot;">​</a></h4><p>若多个扇区连续存放，通常只在开头付一次寻道和平均旋转等待，随后连续传输；若每个块随机散落在不同磁道位置，题目常按“每块都要重新定位”计算。</p><p>例：6000 RPM，平均寻道 5 ms，每道 100 个扇区，读取 4 个扇区。</p><ul><li>一圈时间：<code>60000/6000=10 ms</code>；</li><li>平均旋转等待：<code>10/2=5 ms</code>；</li><li>每扇区传输：<code>10/100=0.1 ms</code>。</li></ul><p>若 4 个扇区<strong>连续</strong>：</p><p><code>T连续 = 5+5+4×0.1 = 10.4 ms</code>。</p><p>若 4 个扇区分别随机位于不同位置，并假定每次都重新寻道、重新等待：</p><p><code>T非连续 = 4×(5+5+0.1) = 40.4 ms</code>。</p><p>反向检查：非连续方案重复支付了 4 次定位成本，时间应明显大于连续方案。题目若说明“同一磁道但不连续”，则是否重复寻道要按题意调整，不能机械乘块数。</p><p><strong>反例</strong>：把“7200 转/分”直接代成 1/7200 秒是错的，单位还在“分钟”；必须先乘 60 秒/分。平均旋转等待不是一整圈，而是半圈。</p><p><strong>应试动作</strong>：容量题画四格乘法；时间题写“寻道+半圈+传输”。看到 RPM 先算一圈毫秒数，最后统一单位。</p><hr>',31)])])}const h=e(r,[["render",s]]);export{m as __pageData,h as default};
